import pandas as pd, numpy as np, json, os
from pathlib import Path

csv='/app/benchmark/data.csv'
df=pd.read_csv(csv)

# ensure output dir
Path('/app/output').mkdir(parents=True, exist_ok=True)

# helpers
h=df['HSC_Result']
prev=df['Previous_GPA']
ssc=df['SSC_Result']

kpis={
 'avg_hsc': h.mean(),
 'excellent_rate': (h>=4.5).mean()*100,
 'atrisk_rate': (h<3.0).mean()*100,
 'gpa_delta': (h-prev).mean(),
 'att_corr': df['Attendance'].corr(h)
}

# Performance bands
bins=[-1,3.0,4.0,4.5,5.01]
labels=['Poor (<3.0)','Average (3.0–3.99)','Good (4.0–4.49)','Excellent (≥4.5)']
df['Perf_Band']=pd.cut(h,bins=bins,labels=labels,right=False)
perf=df['Perf_Band'].value_counts().reindex(labels)
pass_rate=(h>=2.0).mean()*100

# Demographics
age_stats=df['Age'].describe()[['mean','min','max']].to_dict()
gender=df['Gender'].value_counts()
district=df['District'].value_counts().sort_values(ascending=False)
school=df['School_Type'].value_counts()

# Socio-economic analyses
# income quartiles
df['Income_Quartile']=pd.qcut(df['Family_Income_BDT'],4,labels=['Q1 Lowest','Q2','Q3','Q4 Highest'])
income_hsc=df.groupby('Income_Quartile',observed=False)['HSC_Result'].agg(['mean','median','count'])

parent_hsc=df.groupby('Parent_Education')['HSC_Result'].agg(['mean','count']).sort_values('mean')
net_hsc=df.groupby('Internet_Access')['HSC_Result'].agg(['mean','count'])
net_ex=df.groupby('Internet_Access')['HSC_Result'].apply(lambda s:(s>=4.5).mean()*100)
tuit_hsc=df.groupby('Private_Tuition')['HSC_Result'].agg(['mean','count'])

# effect sizes
income_gap=float(income_hsc.loc['Q4 Highest','mean']-income_hsc.loc['Q1 Lowest','mean'])
parent_gap=float(parent_hsc['mean'].max()-parent_hsc['mean'].min())
internet_gap=float(net_hsc['mean'].max()-net_hsc['mean'].min())

test={} 
for col in ['Family_Income_BDT','Attendance','Study_Hours_per_Week','Previous_GPA','SSC_Result']:
    test[col]=float(df[col].corr(h))

# study/attendance patterns
study_bins=[0,8,12,16,30]
study_labels=['Low (≤8)','Moderate (9–12)','High (13–16)','Very High (17+)']
df['Study_Band']=pd.cut(df['Study_Hours_per_Week'],bins=study_bins,labels=study_labels,include_lowest=True)
study_hsc=df.groupby('Study_Band',observed=False)['HSC_Result'].agg(['mean','count'])

att_bins=[0,70,80,90,100]
att_labels=['<70%','70–79%','80–89%','90%+']
df['Att_Band']=pd.cut(df['Attendance'],bins=att_bins,labels=att_labels,include_lowest=True)
att_hsc=df.groupby('Att_Band',observed=False)['HSC_Result'].agg(['mean','count'])

# regional disparities
dist_hsc=df.groupby('District')['HSC_Result'].mean().sort_values(ascending=False)
dist_school=df.pivot_table(index='District',columns='School_Type',values='HSC_Result',aggfunc='mean')
dist_school['Gap_Private-Public']=dist_school.get('Private',np.nan)-dist_school.get('Public',np.nan)

# build simple html with plotly CDN
import json

def j(obj):
    return json.dumps(obj, ensure_ascii=False)

summary={
 'rows':len(df),
 'missing_cells':int(df.isna().sum().sum()),
 'kpis':kpis,
 'pass_rate':pass_rate,
 'age_stats':age_stats,
 'top_district':dist_hsc.index[0],
 'bottom_district':dist_hsc.index[-1],
 'income_gap':income_gap,
 'parent_gap':parent_gap,
 'internet_gap':internet_gap,
 'corrs':test,
}

