study_band={k:mean(study_bands.get(k,[])) for k in study_band_labels}

att_labels=['<70%','70–79%','80–89%','90%+']
att_bands=defaultdict(list)
for r in rows:
    x=r['Attendance']
    if x<70: k=att_labels[0]
