    dist_hsc[d].append(v)
    dist_school[d][s].append(v)

dist_hsc_mean={k:mean(v) for k,v in dist_hsc.items()}
d_sorted=sorted(dist_hsc_mean.items(), key=lambda kv: kv[1], reverse=True)

heat={}
for d in dist_school:
    pub=mean(dist_school[d].get('Public',[])) if dist_school[d].get('Public') else None
    prv=mean(dist_school[d].get('Private',[])) if dist_school[d].get('Private') else None
    gap=(prv-pub) if (pub is not None and prv is not None) else None
    heat[d]={'Public':pub,'Private':prv,'Gap_Private-Public':gap}

corrs={
 'Family_Income_BDT': corr(income,h),
 'Attendance': corr(att,h),
 'Study_Hours_per_Week': corr(study,h),
 'Previous_GPA': corr(prev,h),
 'SSC_Result': corr(ssc,h)
}

missing_cells=0
with open(infile,newline='',encoding='utf-8') as f:
    rr=csv.reader(f)
